{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello इंदर आपको HP EliteBook X2 GR detachable की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "अह piece तो मतलब wholesale चाहिए था ma'am।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "अह 35 piece चाहिए था।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "चलिए अब processor के बारे में बात कर लेते हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए?"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "Intel Core i5 या कुछ और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "ना कौन सा ना वो बता दीजिए।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "अभी वो HP का HP Elite X2 8 Gen."
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "8 दिन का चाहिए sir high five."
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "piece."
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब बताइए RAM में क्या prefer करेंगे 8 GB, 16 GB या कोई और?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "ADGB."
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "मैं देख पा रही हूँ आपको storage capacity 256 GB ही चाहिए ना?"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "हं।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "किसको बोलते हैं direct seller को?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "जी मैं आपको अच्छे sellers से connect करने में मदद करूंगी।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
